 private function lockObject(int$id):void{$this->db->createCommand("INSERT IGNORE INTO `{$this->prefix}fm2_otiz_settlement_locks`(object_id)VALUES(:id)",[':id'=>$id])->execute();$this->db->createCommand("SELECT object_id FROM `{$this->prefix}fm2_otiz_settlement_locks` WHERE object_id=:id FOR UPDATE",[':id'=>$id])->queryScalar();}
 private function updateStatus(int$id,string$status,array$r):void{$this->db->createCommand("UPDATE `{$this->prefix}fm2_otiz_calculation_revisions` SET status=:s,revision=revision+1,updated_at=:at WHERE id=:id",[':s'=>$status,':at'=>($this->clock)(),':id'=>$id])->execute();}private function event(?int$id,string$type,int$a,array$p):void{if($type==='decision_saved'&&$id!==null)$p['decisionId']=(int)$this->db->createCommand("SELECT id FROM `{$this->prefix}fm2_otiz_payment_decisions` WHERE calculation_id=:id ORDER BY id DESC LIMIT 1",[':id'=>$id])->queryScalar();$this->db->createCommand("INSERT INTO `{$this->prefix}fm2_otiz_v2_events`(calculation_id,event_type,payload_json,actor_user_id,created_at)VALUES(:id,:t,:p,:a,:at)",[':id'=>$id,':t'=>$type,':p'=>$this->json($p),':a'=>$a,':at'=>($this->clock)()])->execute();}
 private function withShares(array$p):array{$payable=[];foreach($p['objects']??[]as$object)$payable[(int)$object['objectId']]=(int)($object['payableCents']??0);foreach($p['recipients']??[]as&$recipient){$total=$payable[(int)$recipient['objectId']]??0;$recipient['finalShareBp']=$total>0?intdiv((int)$recipient['amountCents']*10000,$total):0;}unset($recipient);return$p;}
 private function paymentState(int$id):array{$rows=$this->db->createCommand("SELECT p.id,p.amount_cents,EXISTS(SELECT 1 FROM `{$this->prefix}fm2_otiz_payment_reversals` r WHERE r.payment_id=p.id) reversed FROM `{$this->prefix}fm2_otiz_payment_facts` p WHERE p.calculation_id=:id ORDER BY p.id",[':id'=>$id])->queryAll();$paid=0;$active=null;$reversed=false;foreach($rows as$row){if((int)$row['reversed']===1){$reversed=true;continue;}$paid+=(int)$row['amount_cents'];$active=(int)$row['id'];}return['paidCents'=>$paid,'activePaymentId'=>$active,'reversed'=>$reversed];}
 private function json(mixed$v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR);}private function decode(string$v):array{return json_decode($v,true,flags:JSON_THROW_ON_ERROR);}
 private function requireReason(string$reason):void{if(trim($reason)==='')throw new \DomainException('REASON_REQUIRED');}
 private function validPaymentDate(string$date):void{$parsed=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if($parsed===false||$parsed->format('Y-m-d')!==$date)throw new \DomainException('INVALID_PAYMENT_DATE');}
}
